// বাংলা MCQ ডেটা - 74টি প্রশ্ন
var data_bangla = [{"id":"bangla-1","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"ভাষার অর্থযুক্ত ক্ষুদ্রতম একক কোনটি?","options":["অক্ষর","রূপমূল","শব্দ","বর্গ"],"correctIndex":1,"subject":"বাংলা","explanation":"ভাষার মূল উপাদান/ক্ষুদ্রতম একক হলো ধ্বনি, যার নিজস্ব কোনো অর্থ নেই (যেমন: অ, আ, ই, উ)। কিন্তু ভাষা/শব্দের অর্থযুক্ত ক্ষুদ্রতম একক হলো রূপ বা রূপমূল (Morpheme), যার নিজস্ব অর্থ থাকে। যেমন 'পড়ি' শব্দের রূপমূল 'পড়'। রূপমূল থেকে শব্দ গঠিত হয় বলে শব্দতত্ত্বকে রূপতত্ত্ব (Morphology)ও বলা হয়। রূপমূল দুই প্রকার: মুক্ত রূপমূল (নিজে স্বাধীনভাবে অর্থ প্রকাশ করে, যেমন: কাজ, ঘর, চল) ও বদ্ধ রূপমূল (একা অর্থ প্রকাশ করে না, অন্য রূপমূলের সাথে যুক্ত হয়ে অর্থ তৈরি করে, যেমন: টি, গুলো, রা)। অপশন বিশ্লেষণ: অক্ষর (দল) হলো নিঃশ্বাসের স্বল্পতম প্রয়াসে উচ্চারিত ধ্বনি/ধ্বনিগুচ্ছ, উচ্চারণের একক; শব্দ হলো বাক্যের মৌলিক উপাদান, যার গঠনগত উপাদান বর্ণ; বর্গ হলো একাধিক শব্দে গঠিত বাক্যাংশ, বাক্যের একক।"},{"id":"bangla-2","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"ধ্বনি ও বর্ণের পার্থক্য কোথায়?","options":["লেখার ধরনে","উচ্চারণের বিশিষ্টতায়","সংখ্যাগত পরিমাণে","ইন্দ্রিয়গ্রাহ্যে"],"correctIndex":3,"subject":"বাংলা","explanation":"মানুষের কণ্ঠনিঃসৃত আওয়াজ হলো ধ্বনি, আর ধ্বনির লিখিত রূপ বা নির্দেশক প্রতীক/চিহ্ন হলো বর্ণ। ধ্বনি ও বর্ণের মূল পার্থক্য ইন্দ্রিয়গ্রাহ্যে, অর্থাৎ ইন্দ্রিয়ের সাহায্যে বোঝা যায় এমন বিষয়ে। ইন্দ্রিয় বলতে বোঝায় দেহের অঙ্গপ্রত্যঙ্গ ও শক্তি (চক্ষু, কর্ণ, নাসিকা, জিহ্বা, ত্বক, বাক, হস্ত, পদ ইত্যাদি) যা দিয়ে বাহ্য বিষয়ের জ্ঞান ও অনুভূতি উপলব্ধ হয়। অপশন বিশ্লেষণ: লেখার ধরন বা উচ্চারণের বিশিষ্টতায় ধ্বনি ও বর্ণের পার্থক্য করা যায় না, কারণ ধ্বনি মুখে উচ্চারিত হয় আর বর্ণ তারই প্রতীক (যেমন: ক ধ্বনির প্রতীক ক বর্ণ)। এখানে ধ্বনি শ্রুতিগ্রাহ্য আর বর্ণ দৃশ্যমান — অর্থাৎ পার্থক্যটা চোখ, কান ইত্যাদি ইন্দ্রিয়ের সাহায্যে বোধগম্যতায়।"},{"id":"bangla-3","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'মৃগয়া' শব্দের মৃগ বলতে কি বোঝানো হয়?","options":["বানর","সিংহ","পশু","বন"],"correctIndex":2,"subject":"বাংলা","explanation":"বাংলা একাডেমি আধুনিক বাংলা অভিধান অনুযায়ী 'মৃগয়া' শব্দের অর্থ হরিণ শিকার বা বন্য পশুপাখি শিকার। আর 'মৃগ' শব্দের অর্থ পশু, হরিণ। অপশন বিশ্লেষণ: বানর শব্দের সমার্থক শব্দ- শাখামৃগ, মর্কট, বাঁদর; সিংহ শব্দের সমার্থক- কেশরী, পশুরাজ, মৃগরাজ, মৃগেন্দ্র; বন শব্দের সমার্থক- অরণ্য, অটবি, কানন, বিপিন, বনানী, কুঞ্জ, কান্তার, গহন।"},{"id":"bangla-4","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'পরিবার থেকেই শিক্ষার শুরু'-এখানে 'থেকে' শব্দের সাথে যুক্ত 'ই'-এর ব্যাকরণিক পরিচয় কী?","options":["উপসর্গ","প্রত্যয়","ধাতু","বলক"],"correctIndex":3,"subject":"বাংলা","explanation":"যেসব শব্দাংশ পদের সঙ্গে যুক্ত হলে বক্তব্য জোরালো হয়, সেগুলোকে বলক বলে। 'তখনই'/'এখনও' পদের 'ই' বা 'ও' বলকের উদাহরণ। তাই 'পরিবার থেকেই শিক্ষার শুরু' বাক্যে 'থেকে' শব্দের সাথে যুক্ত 'ই' হলো বলক। অপশন বিশ্লেষণ: উপসর্গ শব্দমূলের পূর্বে বসে নতুন শব্দ গঠন করে (যেমন: 'পরিচালক' শব্দের 'পরি'); প্রত্যয় শব্দমূলের পরে বসে নতুন শব্দ গঠন করে (যেমন: 'সাংবাদিক' শব্দের 'ইক'); ধাতু হলো ক্রিয়াপদের মূল অংশ (যেমন: কর্, যা, চল্, ধৃ)।"},{"id":"bangla-5","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'স্বাধীন' শব্দের ব্যাসবাক্য কোনটি?","options":["স্বীয়-এর অধীন","সত্তার অধীন","স্ব-এর অধীন","স্বত্বের অধীন"],"correctIndex":2,"subject":"বাংলা","explanation":"'স্বাধীন' শব্দটি ৬ষ্ঠী তৎপুরুষ সমাসের দৃষ্টান্ত; এর ব্যাসবাক্য হলো- স্ব (নিজ) এর অধীন। পরপদের প্রাধান্য এবং ব্যাসবাক্যে নতুন করে র/এর বিভক্তি এলে ৬ষ্ঠী তৎপুরুষ সমাস হয়। অনুরূপ উদাহরণ: পুষ্পসৌরভ (পুষ্পের সৌরভ), চা-বাগান (চায়ের বাগান), মাতৃসেবা (মায়ের সেবা), এবং পরাধীন, বৈষম্যবিরোধী, গল্পপ্রেমিক, মৃগশিশু, ছাগদুগ্ধ, কন্যাসহ, অপরাহ্ন, পূর্বাহ্ন ইত্যাদি।"},{"id":"bangla-6","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'সত্যেকে স্বীকার করতে অনেক ব্যক্তিরাই চায়না।' এখানে ভুল ঘটেছে-","options":["বানান ও প্রত্যয়ের","অর্থ ও বচনের","অর্থ ও প্রত্যয়ের","বানান ও বচনের"],"correctIndex":3,"subject":"বাংলা","explanation":"প্রশ্নোল্লিখিত বাক্যে বানান ও বচনের ভুল ঘটেছে। ক্রিয়ার সাথে না-বোধক অব্যয় আলাদা বসে, তাই সঠিক বানান হবে- চায় না। আর দুটি বহুবচন শব্দ পাশাপাশি থাকলে একটি বাদ দিতে হয়, তাই সঠিক হবে- অনেক ব্যক্তিই। সুতরাং বাক্যটির সঠিক রূপ: সত্যকে স্বীকার করতে অনেক ব্যক্তিই চায় না।"},{"id":"bangla-7","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'এ কাজ করতে আমি বদ্ধ পরিকর'- এখানে 'পরিকর' শব্দের অর্থ কী?","options":["শ্বাস","প্রতিজ্ঞা","কোমর","প্রতিশ্রুত"],"correctIndex":3,"subject":"বাংলা","explanation":"বাংলা একাডেমি আধুনিক বাংলা অভিধান অনুযায়ী 'পরিকর' শব্দের অর্থ- অনুচর, পরিজন, কটিবদ্ধ (কোমরবদ্ধ), পালঙ্ক। তবে প্রশ্নে উল্লিখিত বাক্যে পরিকর বা বদ্ধপরিকর দ্বারা প্রতিশ্রুত বোঝানো হয়েছে। এছাড়া বদ্ধপরিকর শব্দটি দ্বারা বোঝায়- কোনো কাজ করার জন্য উঠেপড়ে লেগেছে এমন, কোমর বেঁধেছে এমন।"},{"id":"bangla-8","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"কোন শব্দটি বিসর্গসন্ধির মাধ্যমে গঠিত?","options":["নীরব","উজ্জ্বল","মানোন্তীর্ণ","সংগ্রাম"],"correctIndex":0,"subject":"বাংলা","explanation":"নীরব শব্দটি বিসর্গ সন্ধিজাত শব্দ। 'নী'-এর পরে 'র' যুক্ত অর্থপূর্ণ শব্দ (রব, রত, রক্ত, রোগ) থাকলে 'নী' পরিবর্তিত হয়ে 'নিঃ' হয়ে যায়— নীরব = নিঃ + রব; নীরত = নিঃ + রত; নীরক্ত = নিঃ + রক্ত; নীরোগ = নিঃ + রোগ। অপশন বিশ্লেষণ: উজ্জ্বল = উৎ + জ্বল (ব্যঞ্জনসন্ধি); মানোন্তীর্ণ = মান + উত্তীর্ণ (স্বরসন্ধি); সংগ্রাম = সম্ + গ্রাম (ব্যঞ্জনসন্ধি)।"},{"id":"bangla-9","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"কোন ধ্বনি পরিবর্তনটি যথাযথ নয়?","options":["ক্রন্দন > কাঁদা","অঞ্চল > আঁচল","সংগীত > গীতিকা","দন্ত > দাঁত"],"correctIndex":2,"subject":"বাংলা","explanation":"ধ্বনির পরিবর্তন হলো উচ্চারণের পরিবর্তন; সম্পূর্ণ নতুন শব্দ গঠিত হলে সেটি ধ্বনির পরিবর্তন নয়। সংগীত > গীতিকায় সম্পূর্ণ নতুন শব্দ গঠিত হয়েছে, তাই এই পরিবর্তনটি যথাযথ নয়। অপশন বিশ্লেষণ: ক্রন্দন > কাঁদা, অঞ্চল > আঁচল, দন্ত > দাঁত শব্দগুলোতে যথাযথভাবে নাসিক্যীভবন (নাসিক্য ব্যঞ্জন ঙ, ঞ, ণ, ন, ম লুপ্ত হয়ে আগের স্বরধ্বনি অনুনাসিক/চন্দ্রবিন্দু হওয়া) ঘটেছে, যেমন অঙ্কন > আঁকা। অনুরূপ: কণ্টক > কাঁটা, কম্পন > কাঁপা।"},{"id":"bangla-10","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'উৎক্ষেপণ' শব্দের 'উৎ' উপসর্গ কোন অর্থ ধারণ করেছে?","options":["জোর","ঊর্ধ্ব","আড়াল","গতি"],"correctIndex":1,"subject":"বাংলা","explanation":"উৎক্ষেপণ শব্দের অর্থ- ঊর্ধ্বে ক্ষেপণ (নিক্ষেপ)। এখানে 'উৎ' উপসর্গটি 'উপরের দিকে' বা 'ঊর্ধ্ব' অর্থ প্রকাশ করে। 'উৎ' উপসর্গ যেসব অর্থ ধারণ করে: ঊর্ধ্বে (উৎক্ষিপ্ত, উদগ্রীব, উত্তোলন, উদ্যম, উন্নতি), প্রস্তুতি (উৎপাদন, উচ্চারণ), আতিশয্য (উৎসুক, উৎফুল্ল, উৎসুক), বাহির (উন্মনা)।"},{"id":"bangla-11","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"কোন্ শব্দটি প্রত্যয়যোগে গঠিত?","options":["ডাক্তারখানা","হাসপাতাল","আকাশছোঁয়া","গুণমান"],"correctIndex":0,"subject":"বাংলা","explanation":"প্রকৃতির পরে যে শব্দাংশ যুক্ত হয়ে নতুন শব্দ তৈরি করে তাকে প্রত্যয় বলে (যেমন: প্রাচুর্য = প্রচুর+য, মশারি = মশা+আরি)। ডাক্তারখানা শব্দটি গঠিত হয়েছে 'খানা (বিদেশি)' প্রত্যয় দিয়ে; অনুরূপ: বৈঠকখানা, ছাপাখানা, কারিগর, নজরবন্দি, রাজবন্দি, চৌকিদার, হাবিলদার, জুতসই। অপশন বিশ্লেষণ: হাসপাতাল বিদেশি শব্দ, কোনো প্রত্যয় যুক্ত হয়নি; আকাশছোঁয়া সমাসযোগে গঠিত শব্দ (আকাশকে ছোঁয়া); গুণমান অশুদ্ধ শব্দ, সঠিক শব্দ গুণবান।"},{"id":"bangla-12","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"রবীন্দ্রনাথ ঠাকুর শব্দের শুরুতে মাত্রাযুক্ত এ-কার ব্যবহার করতেন কেন?","options":["এ-কার মাত্রা যুক্ত বলে","'এ' মাত্রাহীন বর্ণ বলে","'এ' উচ্চারণ বোঝাতে","'অ্যা' উচ্চারণ বোঝাতে"],"correctIndex":3,"subject":"বাংলা","explanation":"এ ধ্বনির দুটি উচ্চারণ হয়: এ > এ (সংবৃত) এবং এ > অ্যা (বিবৃত)। শব্দের শুরুতে এ-কারের উচ্চারণ সাধারণত সংবৃত হয় (যেমন: বেশি, মেয়ে)। তবে রবীন্দ্রনাথ ঠাকুর শব্দের শুরুতে মাত্রাযুক্ত এ-কার ব্যবহার করতেন 'অ্যা' উচ্চারণ বোঝাতে, যেমন এক [অ্যাক্], খেলা [খ্যালা], যেমন [জ্যামোন্]।"},{"id":"bangla-13","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"পারিভাষিক শব্দ বলতে বুঝায়-","options":["ইংরেজি শব্দের বাংলা রূপান্তর","বিদেশি শব্দের অনুবাদ","বিষয়গত সুনির্দিষ্ট অর্থবোধক শব্দ","ব্যবহারিক প্রয়োজনে নবনির্মিত শব্দ"],"correctIndex":2,"subject":"বাংলা","explanation":"পরিভাষা হলো বিশেষ অর্থ প্রকাশকারী শব্দ বা শব্দরাশি। যে সুনির্দিষ্ট অর্থবোধক শব্দ দ্বারা কোনো বিষয়কে ব্যক্ত করা যায় তা-ই পারিভাষিক শব্দ; এগুলো নির্দিষ্ট বিষয়, শাস্ত্র বা ক্ষেত্রের সাথে সম্পর্কিত। যেমন: Acting- ভারপ্রাপ্ত; Amicus curie- আদালতের বন্ধু; Pedagogy- শিক্ষণবিজ্ঞান/শিক্ষাতত্ত্ব; Heavenly body- জ্যোতিষ্ক।"},{"id":"bangla-14","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'তিনি কথা শুনে ঘুমাতে পারলেন না'- বাক্যটির অস্তিবাচক রূপ কী হবে?","options":["তিনি কথা না শুনে ঘুমাতে পারলেন না","তিনি কথা না শুনে ঘুমাতে পারলেন","তিনি জেগে রইলেন কথা না শুনে","তিনি কথা শুনে জেগে রইলেন"],"correctIndex":3,"subject":"বাংলা","explanation":"নেতিবাচক বাক্যকে অস্তিবাচক বাক্যে রূপান্তরের নিয়ম: (১) মূল অর্থ পরিবর্তন হবে না, (২) না-বোধক শব্দ বাদ দিতে হবে, (৩) প্রয়োজনে বিপরীত শব্দ ব্যবহার করা যাবে। এই নিয়ম অনুসারে 'তিনি কথা শুনে ঘুমাতে পারলেন না'-এর অস্তিবাচক রূপ: তিনি কথা শুনে জেগে রইলেন। এখানে মূল অর্থের পরিবর্তন হয়নি; না-বোধক শব্দ বাদ হয়েছে এবং বিপরীতধর্মী শব্দ বসেছে।"},{"id":"bangla-15","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'শিক্ষককে বুঝতে হবে শিক্ষার্থী কী চায়'- এই বাক্যে শিক্ষক ও শিক্ষার্থীর প্রয়োগ হয়েছে-","options":["একবচন বোঝাতে","বহুবচন বোঝাতে","একবচন ও বহুবচন উভয়ই বোঝাতে","প্রথমটি একবচন, পরেরটি বহুবচন বোঝাতে"],"correctIndex":1,"subject":"বাংলা","explanation":"এই বাক্যে শিক্ষক শব্দটি দ্বারা শিক্ষক জাতি/সকল শিক্ষক এবং শিক্ষার্থী শব্দটি দ্বারা শিক্ষার্থী জাতি/সকল শিক্ষার্থীকে বোঝানো হয়েছে। অর্থাৎ প্রশ্নোল্লিখিত বাক্যটি দ্বারা শিক্ষক ও শিক্ষার্থী উভয়েরই বহুবচন প্রয়োগ ঘটেছে।"},{"id":"bangla-16","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"ভাষা-পরিবার অনুযায়ী সাঁওতাল জনগোষ্ঠী প্রধানত কোন পরিবারভুক্ত?","options":["ইন্দো-আর্য","দ্রাবিড়","অস্ত্রিক-অস্ট্রো এশিয়াটিক (মুন্ডা)","তিব্বত-বর্মী"],"correctIndex":2,"subject":"বাংলা","explanation":"সাঁওতাল জনগোষ্ঠী অস্ত্রিক ভাষী; ভাষা-পরিবার অনুযায়ী এরা অস্ত্রিক-অস্ট্রো এশিয়াটিক (মুন্ডা) পরিবারভুক্ত। কোল ও মুন্ডারি ভাষার সঙ্গে সাঁওতালি ভাষার সাদৃশ্য রয়েছে; এরা আদি-অস্ট্রেলীয় (প্রোটো-অস্ট্রালয়েড) জনগোষ্ঠীর বংশধর। সাঁওতালরা ভারতীয় উপমহাদেশের অন্যতম আদি বাসিন্দা এবং কৃষি উৎপাদন ব্যবস্থা ও কৃষিসংস্কৃতির জনক-ধারক হিসেবে স্বীকৃত; তাদের বাসস্থান মূলত রাজশাহী, দিনাজপুর, রংপুর ও বগুড়া জেলায়, আর প্রধান নিবাস রাঢ়বঙ্গ, বিহার-উড়িষ্যার অরণ্য অঞ্চল ও ছোটনাগপুর। তাদের বছর শুরু হয় ফাল্গুন মাসে, আর পৌষ সংক্রান্তিতে পালিত হয় সোহরাই উৎসব।"},{"id":"bangla-17","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'কম দামে কেনা বেশী দামে বেচা আমাদের স্বাধীনতা'-বইটির লেখক কে?","options":["আবুল কালাম শামসুদ্দীন","আবুল মনসুর আহমদ","শামসুদ্দিন আবুল কালাম","এস ওয়াজেদ আলী"],"correctIndex":1,"subject":"বাংলা","explanation":"'বেশী দামে কেনা কম দামে বেচা আমাদের স্বাধীনতা' গ্রন্থটির রচয়িতা রম্য রচনার বিখ্যাত লেখক আবুল মনসুর আহমদ। এই গ্রন্থে ৪২টি নিবন্ধ রয়েছে, যার মধ্যে প্রথম ৩৯টি ১৯৭২ ও ১৯৭৩ সালে দৈনিক ইত্তেফাকে প্রকাশিত হয়েছিল।"},{"id":"bangla-18","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"চর্যাপদের খণ্ডিত পদগুলো তিব্বতি থেকে প্রাচীন বাংলায় রূপান্তর করেন-","options":["সুনীতিকুমার চট্টোপাধ্যায়","হরপ্রসাদ শাস্ত্রী","রাজেন্দ্রলাল মিত্র","সুকুমার সেন"],"correctIndex":3,"subject":"বাংলা","explanation":"চর্যাপদ তিব্বতি ভাষায় অনুবাদ করেন কীর্তিচন্দ্র; তবে চর্যাপদের তিব্বতি অনুবাদকে বাংলায় রূপান্তর করেন সুকুমার সেন। চর্যাপদের আবিষ্কৃত পদের সংখ্যা সাড়ে ছেচল্লিশটি (ড. মুহম্মদ শহীদুল্লাহর মত)। ২৩ নং পদটি (ভুসুকুপা রচিত) খণ্ডিত আকারে ৬ লাইন পাওয়া গেলেও বাকি ৪ লাইন পাওয়া যায়নি; এছাড়া ২৪ নং (কাহ্নপা), ২৫ নং (তন্ত্রীপা) ও ৪৮ নং (কুক্কুরীপা) পদগুলো পাওয়া যায়নি। যেহেতু সুকুমার সেন সম্পূর্ণ চর্যাপদের তিব্বতি অনুবাদকে বাংলায় রূপান্তর করেন, তাই খণ্ডিত ও হারানো পদগুলো (২৩, ২৪, ২৫ ও ৪৮) তিনিই তিব্বতি থেকে বাংলায় রূপান্তর করেন।"},{"id":"bangla-19","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"আহমদ শরীফের মতে মধ্যযুগে চণ্ডীদাস নামে কতজন কবি ছিলেন?","options":["২","৩","৪","৫"],"correctIndex":1,"subject":"বাংলা","explanation":"মধ্যযুগে বাংলা সাহিত্যের অঙ্গনে চারজন চণ্ডীদাসের আবির্ভাব ঘটেছিল বলে সাধারণত মনে করা হয়- বড়ু চণ্ডীদাস, দ্বিজ চণ্ডীদাস, দীন চণ্ডীদাস ও চণ্ডীদাস (কেউ কেউ দ্বিজ ও দীন চণ্ডীদাসকে একই ব্যক্তি মনে করেন)। তাদের জন্মের স্থান-কাল ও সাহিত্যকর্ম নিয়ে মতবিরোধ ও অস্পষ্টতা 'চণ্ডীদাস সমস্যা' নামে পরিচিত। ড. আহমদ শরীফের মতে অবশ্য মধ্যযুগে চণ্ডীদাস নামে ৩ জন কবি ছিলেন: (১) অনন্ত বড়ু চণ্ডীদাস- সর্বপ্রাচীন চণ্ডীদাস, (২) চণ্ডীদাস- চৈতন্য পূর্বকালের বা জ্যেষ্ঠ সমসাময়িক, (৩) দীন চণ্ডীদাস- আঠারো শতকের শেষার্ধ।"},{"id":"bangla-20","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"'যে আলোতে কুমুদ ফোটে'- এককথায় কী হবে?","options":["কুমুদিন","কৌমুদী","প্রভাবতী","বিভা"],"correctIndex":1,"subject":"বাংলা","explanation":"কুমুদ শব্দের অর্থ পদ্ম। যে আলোতে কুমুদ ফোটে তাকে বলে কৌমুদী; কৌমুদী শব্দের অর্থ চাঁদের আলো, জ্যোৎস্না। কৌমুদী সংস্কৃত শব্দ, যার প্রকৃতি ও প্রত্যয় হলো কুমুদ+অ+ঈ। অপশন বিশ্লেষণ: কুমুদিন নামে কোনো শব্দ নেই (কুমুদিনী/মৃণালিনী শব্দের অর্থ পদ্মের ঝাড়); প্রভাবান শব্দের অর্থ দীপ্তিমান/উজ্জ্বল, যার স্ত্রীবাচক রূপ প্রভাবতী; বিভা শব্দের অর্থ আলোক, কিরণ, প্রভা।"},{"id":"bangla-21","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"কোন শব্দে দ্বিস্বরধ্বনি রয়েছে?","options":["তিসি","মালি","লাউ","মেয়ে"],"correctIndex":2,"subject":"বাংলা","explanation":"পূর্ণ স্বরধ্বনি ও অর্ধস্বরধ্বনি একত্রে উচ্চারিত হলে দ্বিস্বরধ্বনি বা যৌগিক স্বরধ্বনি সৃষ্টি হয়। লাউ শব্দে পূর্ণ স্বরধ্বনি [আ] ও অর্ধস্বরধ্বনি [উ] মিলে দ্বিস্বরধ্বনি [আউ] তৈরি হয়েছে। দ্বিস্বরধ্বনির আরও উদাহরণ: [আই]-তাই,নাই; [আও]-যাও,দাও; [আএ]-খায়,যায়; [অএ]-নয়,হয়; [এই]-সেই,নেই; [এউ]-কেউ,ঘেউ; [ওই]-কৈ,দই; [ওউ]-মৌ,বউ। অপশন বিশ্লেষণ: তিসি (ত্+ই+স্+ই), মালি (ম্+আ+ল্+ই), মেয়ে (ম্+এ+য়্+এ)- এই তিনটি শব্দে দুটি করে পৃথক (একক) স্বরধ্বনি আছে, দ্বিস্বরধ্বনি নয়।"},{"id":"bangla-22","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"প্রত্যয়যোগে গঠিত শব্দ কোনটি?","options":["ডাক্তারখানা","অনুগমন","দিলখোলা","সম্রাট"],"correctIndex":0,"subject":"বাংলা","explanation":"ডাক্তারখানা শব্দটি 'ডাক্তার+খানা' (তদ্ধিত প্রত্যয়যোগে) গঠিত। অনুগমন (পশ্চাৎ গমন) অব্যয়ীভাব সমাসে এবং দিলখোলা (দিল খোলা যার) বহুব্রীহি সমাসে গঠিত শব্দ। সম্রাট শব্দটিও কৃৎ প্রত্যয়যোগে (সম্+√রাজ্+অ) গঠিত বলে কোনো কোনো ব্যাখ্যায় উল্লেখ থাকলেও, বিপিএসসির প্রকাশিত সরকারি উত্তরমালা অনুযায়ী এই প্রশ্নের চূড়ান্ত সঠিক উত্তর নির্ধারিত হয়েছে ডাক্তারখানা।"},{"id":"bangla-23","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"'তিনি কথা বললেন না।'-বাক্যটির অস্তিবাচক রূপ কী হবে?","options":["তিনি কথা বলতে চাইলেন না।","তিনি কথা না বলে থাকতে পারলেন না।","তিনি নীরব থাকতে চেষ্টা করলেন।","তিনি চুপ করে থাকলেন।"],"correctIndex":3,"subject":"বাংলা","explanation":"নেতিবাচক বাক্যকে অস্তিবাচক বাক্যে রূপান্তরের নিয়ম: (১) মূল অর্থের পরিবর্তন হবে না, (২) না-বোধক শব্দ বাদ দিতে হবে, (৩) প্রয়োজনে বিপরীতধর্মী শব্দ ব্যবহার করা যাবে। এই নিয়ম অনুযায়ী 'তিনি কথা বললেন না।'-এর অস্তিবাচক রূপ হলো 'তিনি চুপ করে থাকলেন।' অনুরূপ উদাহরণ: 'মিথ্যাবাদীকে কেউ পছন্দ করে না' → 'মিথ্যাবাদীকে সবাই অপছন্দ করে'; 'তপুর আগে কেউ উঠতে পারত না' → 'তপু সবার আগে উঠত'; 'তাতে সমাজজীবন চলে না' → 'তাতে সমাজজীবন অচল হয়ে পড়ে'।"},{"id":"bangla-24","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"'অন্তর্ভুক্তিমূলক' শব্দ উচ্চারণে কয়টি অক্ষর পাওয়া যায়?","options":["৫","৬","৭","৮"],"correctIndex":1,"subject":"বাংলা","explanation":"নিঃশ্বাসের স্বল্পতম প্রয়াসে উচ্চারিত ধ্বনি বা ধ্বনিগুচ্ছকে অক্ষর বলে। সংশ্লিষ্ট টেকনিক- একটি শব্দে যতগুলো স্বরধ্বনি/স্বরচিহ্ন থাকে, সেই শব্দে ততগুলো অক্ষর থাকে। অন্তর্ভুক্তিমূলক শব্দ ভাঙলে পাওয়া যায়- অন্+তর্+ভুক্+তি+মূ+লক্, অর্থাৎ এতে ৬টি স্বরধ্বনি তথা ৬টি অক্ষর আছে। তুলনায়: বন্ধন = বন্+ধন (২টি অক্ষর), মা (১টি অক্ষর), বিশ্ববিদ্যালয় = বি+শ্ব+বি+দ্যা+লয় (৫টি অক্ষর)।"},{"id":"bangla-25","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"শুদ্ধ বাক্য কোনটি?","options":["সারা দেশব্যাপী দিবসটি উদ্‌যাপন করা হবে।","সারা দেশে দিবসটি উদ্যাপন করা হবে।","দেশব্যাপী দিবসটি উদ্যাপন করা হবে।","সারা দেশে দিবসটি উদ্‌যাপন করা হবে।"],"correctIndex":3,"subject":"বাংলা","explanation":"শুদ্ধ বাক্য নির্ণয়ে বানান ও ব্যাকরণসম্মত নিয়ম যথাযথভাবে প্রয়োগ করতে হয়; প্রশ্নে শুদ্ধ বাক্য হলো 'সারা দেশে দিবসটি উদ্‌যাপন করা হবে।' অপশন (ক)-তে 'সারা দেশব্যাপী' প্রয়োগ অশুদ্ধ, কারণ দেশব্যাপী অর্থই সমগ্র দেশে পরিব্যাপ্ত; এর আগে আবার 'সারা' বসালে অর্থ দাঁড়ায় 'সারা সমগ্র দেশে পরিব্যাপ্ত', যা বাহুল্য দোষে দুষ্ট। অপশন (খ) ও (গ)-তে 'উদ্যাপন' বানানটি ভুল। (উল্লেখ্য, মূল প্রশ্নপত্রেই অপশন (খ) ও (ঘ)-এর টেক্সট হুবহু একরকম মুদ্রিত হয়েছিল বলে একাধিক স্বতন্ত্র সমাধান-সূত্রেও পাওয়া যায়; সরকারি উত্তরমালায় নির্ধারিত সঠিক উত্তর অপশন (ঘ)।)"},{"id":"bangla-26","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"ক্রিয়া পদের মূল অংশকে কী বলে?","options":["কর্ম","ধাতু","প্রত্যয়","বিভক্তি"],"correctIndex":1,"subject":"বাংলা","explanation":"ক্রিয়াপদের মূল অংশকে বলা হয় ধাতু বা ক্রিয়ামূল। ক্রিয়াপদকে বিশ্লেষণ করলে দুটি অংশ পাওয়া যায়- প্রথম অংশ ধাতু/ক্রিয়ামূল এবং দ্বিতীয় অংশ ক্রিয়াবিভক্তি। ধাতু তিন প্রকার- মৌলিক ধাতু, সাধিত ধাতু ও যৌগিক ধাতু। অপশন বিশ্লেষণ: কর্তা যাকে আশ্রয় করে ক্রিয়া সম্পাদন করে তাকে কর্ম বলে; নাম প্রকৃতি বা ক্রিয়া প্রকৃতির পরে যুক্ত হয়ে শব্দ গঠনকারী শব্দাংশকে প্রত্যয় বলে; বাক্যস্থিত একটি শব্দের সঙ্গে অন্য শব্দের অন্বয় সাধনের জন্য যুক্ত বর্ণকে বিভক্তি বলে।"},{"id":"bangla-27","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"'আফতাব' শব্দের সমার্থক শব্দ কোনটি?","options":["অর্ণব","রাতুল","অর্ক","জলধি"],"correctIndex":2,"subject":"বাংলা","explanation":"'আফতাব' শব্দের সমার্থক শব্দ- অর্ক, সূর্য, রবি, আদিত্য, দিবাকর, পূষা, সবিতা, প্রভাকর, তপন, ভানু, ভাস্কর, দিনেশ, মার্তণ্ড, দিনকর প্রভৃতি। অপশন বিশ্লেষণ: রাতুল অর্থ লাল বা রক্তবর্ণ; জলধি ও অর্ণব উভয়ই সমুদ্র বোঝায়।"},{"id":"bangla-28","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"বাক্যের অন্তর্গত শব্দের পারস্পরিক সম্পর্ক ব্যাকরণের কোন অংশে আলোচিত হয়?","options":["সন্ধি","পদ","কাল","কারক"],"correctIndex":3,"subject":"বাংলা","explanation":"বাক্যস্থিত ক্রিয়াপদের সাথে নামপদের সম্পর্ককে কারক বলে; বাক্যের অন্তর্গত শব্দের পারস্পরিক সম্পর্ক কারকে আলোচিত হয়, আর কারক বাক্যতত্ত্বের আলোচ্য বিষয়। অপশন বিশ্লেষণ: সন্নিহিত দুটি ধ্বনির মিলনকে সন্ধি বলে, যার উদ্দেশ্য ধ্বনিগত মাধুর্য সৃষ্টি ও উচ্চারণ সহজবোধ্য করা; বিভক্তিযুক্ত শব্দ/ধাতু বা বাক্যে ব্যবহৃত প্রতিটি অর্থবোধক শব্দকে পদ বলে; ক্রিয়া সম্পন্ন হওয়ার সময়কে (বর্তমান/অতীত/ভবিষ্যৎ) কাল বলে।"},{"id":"bangla-29","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"অনুভূতিজাত দ্বিরুক্ত শব্দ কোনটি?","options":["ছমছম","ঝমঝম","টিকটিক","ঠিক ঠিক"],"correctIndex":0,"subject":"বাংলা","explanation":"যেসব দ্বিরুক্ত শব্দ দ্বারা আওয়াজ ছাড়া কেবল অনুভূতি প্রকাশ পায়, সেগুলো অনুভূতিজাত দ্বিরুক্ত শব্দ; যেমন- ছমছম (ভীতিজনিত শিহরনের ভাব), টনটন (দুঃসহ ব্যথার ভাব), বাঁ বাঁ (প্রখরতার ভাব), খাঁ খাঁ (শূন্যতার ভাব)। অপশন বিশ্লেষণ: ঝমঝম ও টিকটিক আওয়াজ/ধ্বনিব্যঞ্জনা বোঝায় (ঝমঝম- বৃষ্টি পড়ার অনুকার শব্দ; টিকটিক- টিকটিকির ডাক); ঠিক ঠিক শব্দটি আওয়াজ বা অনুভূতি কোনোটিই বোঝায় না, এর অর্থ ঠিকমতো/যথার্থ।"},{"id":"bangla-30","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"কোন বানানটি প্রমিত?","options":["পশ্চাদপদ","পশ্চাৎগামী","পশ্চাদ্‌ভূমি","পশ্চাৎবর্তী"],"correctIndex":2,"subject":"বাংলা","explanation":"প্রমিত/সঠিক বানান পশ্চাদ্‌ভূমি (অর্থ- পেছনের স্থান, পটভূমি); এর সন্ধিবিচ্ছেদ পশ্চাৎ+ভূমি। নিয়ম হলো- পশ্চাৎ ও পশ্চাৎপদ এই দুটি শব্দে খণ্ড-ত (ৎ) অক্ষুণ্ন থাকে; এই দুটি ছাড়া অন্য যেসব শব্দে পশ্চাৎ-এর পরে ভ, গ, দ-জাতীয় ধ্বনি বসে সেখানে সাধারণত 'দ' হয়, যেমন- পশ্চাদ্‌ভূমি, পশ্চাদ্গামী, পশ্চাদ্দেশ, পশ্চাদ্বর্তী, পশ্চাদপসারণ। এই নিয়মে অপশন (ক) পশ্চাদপদ ভুল (শুদ্ধ: পশ্চাৎপদ) এবং অপশন (খ) পশ্চাৎগামী ভুল (শুদ্ধ: পশ্চাদ্গামী)। অপশন (ঘ) পশ্চাৎবর্তীও অপ্রমিত রূপ (শুদ্ধ রূপ পশ্চাদ্বর্তী), তাই এই চারটির মধ্যে কেবল অপশন (গ) পশ্চাদ্‌ভূমি-ই প্রমিত বানান।"},{"id":"bangla-31","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"বাংলা অব্যয়ীভাব সমাসের উদাহরণ ব্যাকরণের কোন অংশের অন্তর্ভুক্ত করা যায়?","options":["সন্ধি","উপসর্গ","কারক","প্রত্যয়"],"correctIndex":1,"subject":"বাংলা","explanation":"অব্যয়ীভাব সমাসের পূর্বপদে উপসর্গ থাকে বলে এর উদাহরণগুলো উপসর্গের অন্তর্ভুক্ত করা যায়। যেমন- আমরণ, হাভাত, গরমিল, উপকূল, অনুদিন, অতিমানব, প্রতিবাদ প্রভৃতি অব্যয়ীভাব সমাসের উদাহরণ, যেখানে প্রতিটি শব্দের শুরুতে উপসর্গ (আ, হা, গর, উপ, অনু, অতি, প্রতি) রয়েছে।"},{"id":"bangla-32","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"কোনটি বিশেষণ?","options":["সৎ","একতা","দর্শন","জনতা"],"correctIndex":0,"subject":"বাংলা","explanation":"যে পদ অন্য পদের দোষ, গুণ, অবস্থা, সংখ্যা, পরিমাণ ইত্যাদি প্রকাশ করে তাকে বিশেষণ পদ বলে; যেমন- সৎ ব্যক্তি, সুন্দর পৃথিবী, চলন্ত গাড়ি, দুই ছেলে, তাজা মাছ। অপশন বিশ্লেষণ: একতা, দর্শন, জনতা- এই তিনটি শব্দ বিশেষ্য পদের উদাহরণ।"},{"id":"bangla-33","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"ছড়ার ছন্দকে কী বলে?","options":["স্বরবৃত্ত","মাত্রাবৃত্ত","অক্ষরবৃত্ত","গদ্যছন্দ"],"correctIndex":0,"subject":"বাংলা","explanation":"কাব্যের গতিসৌন্দর্য বিধায়ক স্বতঃস্ফূর্ত নির্মাণকৌশলকে ছন্দ বলে। বাংলা ছন্দ প্রধানত তিন প্রকার- স্বরবৃত্ত, অক্ষরবৃত্ত ও মাত্রাবৃত্ত। স্বরবৃত্ত ছন্দকে বলা হয় লৌকিক ছন্দ/ছড়ার ছন্দ/শ্বাসাঘাত প্রধান ছন্দ; অনেকের মতে আধুনিক স্বরবৃত্ত ছন্দ মধ্যযুগীয় কাব্য শ্রীকৃষ্ণকীর্তনের ধামালি ছন্দ থেকে উদ্ভূত। মাত্রাবৃত্ত ছন্দকে ছন্দের ক্ষেত্রে রবীন্দ্রনাথের শ্রেষ্ঠ অবদান বলে মনে করা হয়, একে ধ্বনিপ্রধান/বিস্তারপ্রধান/সরল কলামাত্রিক ছন্দও বলা হয়। অক্ষরবৃত্ত ছন্দ বাংলা কাব্যের প্রধান ছন্দ, একে তানপ্রধান ছন্দ/তত্ত্ব ছন্দ/আধুনিক মাত্রা ছন্দও বলা হয়; এই ছন্দের ভিত্তিতে সৃষ্ট অন্ত্যমিলহীন রূপকে অমিত্রাক্ষর ছন্দ বলে।"},{"id":"bangla-34","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"Transparency শব্দের বাংলা পরিভাষা কী?","options":["যথার্থতা","নির্ভরযোগ্যতা","স্বচ্ছতা","দুর্নীতিদমন"],"correctIndex":2,"subject":"বাংলা","explanation":"Transparency শব্দের বাংলা পরিভাষা স্বচ্ছতা (Transparent অর্থ স্বচ্ছ)। অপশন বিশ্লেষণ: Accuracy-র পরিভাষা যথার্থতা, Reliability-র পরিভাষা নির্ভরযোগ্যতা, আর Anti-Corruption-এর পরিভাষা দুর্নীতিদমন।"},{"id":"bangla-35","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"সাহিত্য","question":"ফররুখ আহমদের 'সাত সাগরের মাঝি' কত সালে প্রকাশিত হয়?","options":["১৯০৫","১৯৪০","১৯৪৪","১৯৫৫"],"correctIndex":2,"subject":"বাংলা","explanation":"মুসলিম রেনেসাঁর কবি ও ইসলামি আদর্শের উজ্জ্বল প্রতীক ফররুখ আহমদের শ্রেষ্ঠ কাব্যগ্রন্থ 'সাত সাগরের মাঝি', যা ১৯৪৪ সালে প্রকাশিত হয়; এর মূল উপজীব্য ইসলামের ইতিহাস ও ঐতিহ্য। তাঁর অন্যান্য উল্লেখযোগ্য রচনা- হাতেমতায়ী (কাহিনিকাব্য, যার জন্য তিনি আদমজী পুরস্কার লাভ করেন), মুহূর্তের কবিতা (সনেট সংকলন), নৌফেল ও হাতেম (কাব্যনাট্য), সিরাজাম মুনীরা; শিশুতোষ গ্রন্থ পাখির বাসা (তাঁর প্রথম প্রকাশিত শিশুতোষ গ্রন্থ, যার জন্য ইউনেস্কো পুরস্কার লাভ করেন), নতুন লেখা, ছড়ার আসর, চাঁদের আসর, চিড়িয়াখানা, ফুলের জলসা, হরফের ছড়া; বিখ্যাত কবিতা- পাঞ্জেরি, উপহার, স্মরণী।"},{"id":"bangla-36","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"সাহিত্য","question":"'ইউসুফ-জোলেখা'র কবি শাহ মুহম্মদ সগীরের জন্ম কোথায়?","options":["বগুড়া","সিলেট","নদীয়া","চট্টগ্রাম"],"correctIndex":3,"subject":"বাংলা","explanation":"বাংলা সাহিত্যের প্রথম মুসলমান কবি শাহ মুহম্মদ সগীর (পনেরো শতকের কবি) সুলতান গিয়াসউদ্দীন আযম শাহের রাজকর্মচারী/সভাকবি ছিলেন এবং তাঁরই পৃষ্ঠপোষকতায় 'ইউসুফ-জোলেখা' রোমান্টিক প্রণয়োপাখ্যান রচনা করেন। তাঁর জন্মস্থান নিয়ে সরাসরি কোনো তথ্য পাওয়া না গেলেও, তাঁর কাব্যে তৎকালীন চট্টগ্রাম অঞ্চলের ভাষার প্রয়োগ থাকায় ধারণা করা হয় তিনি চট্টগ্রামের অধিবাসী ছিলেন। বাংলা রোমান্টিক প্রণয়োপাখ্যান ধারার আদি কবি/প্রথম বাঙালি কবি হিসেবে তিনি পরিচিত।"},{"id":"bangla-37","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"সাহিত্য","question":"'আজ চারদিক হতে ধনিক বণিক শোষণকারীর জাত, ও ভাই জোঁকের মতন শুষছে রক্ত, কাড়ছে থালার ভাত।'-কার লেখা?","options":["রবীন্দ্রনাথ ঠাকুর","কাজী নজরুল ইসলাম","গোলাম মোস্তফা","সত্যেন্দ্রনাথ দত্ত"],"correctIndex":1,"subject":"বাংলা","explanation":"উদ্ধৃতাংশটি বিদ্রোহী কবি কাজী নজরুল ইসলাম রচিত 'সর্বহারা' কাব্যগ্রন্থের অন্তর্গত 'কৃষাণের গান' কবিতার অংশ, যেখানে কবির বিদ্রোহী সত্তা ও শোষিত-বঞ্চিত কৃষক সমাজের প্রতি সহমর্মিতা প্রকাশ পেয়েছে।"},{"id":"bangla-38","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"সাহিত্য","question":"ইসমাইল হোসেন সিরাজীর কোন কাব্যটি বাজেয়াপ্ত হয়?","options":["'অনল প্রবাহ'","'আকাঙ্ক্ষা'","'উদ্বোধন'","'নব উদীপনা'"],"correctIndex":0,"subject":"বাংলা","explanation":"মুসলিম পুনর্জাগরণবাদী কবি সৈয়দ ইসমাইল হোসেন সিরাজীর প্রথম ও শ্রেষ্ঠ কাব্যগ্রন্থ 'অনল প্রবাহ' (১৯০০); মুসলিম জাগরণমূলক এই কাব্যে ইংরেজবিরোধী তীব্র মনোভাব প্রকাশ পাওয়ায় গ্রন্থটি ইংরেজ সরকার কর্তৃক নিষিদ্ধ/বাজেয়াপ্ত হয়। তাঁর অন্যান্য কাব্যগ্রন্থ- স্পেন বিজয় কাব্য (মহাকাব্য), আকাঙ্ক্ষা, উচ্ছ্বাস, নব উদীপনা, সঙ্গীত সঞ্জীবনী, প্রেমাঞ্জলি; উপন্যাস- রায়নন্দিনী, তারাবাঈ, ফিরোজা বেগম, নূরউদ্দীন।"},{"id":"bangla-39","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"সাহিত্য","question":"'শ্রীকৃষ্ণকীর্তন' কাব্যের প্রথম খণ্ডের নাম কী?","options":["জন্মখণ্ড","তাম্বুলখণ্ড","দানখণ্ড","রাধাবিরহ"],"correctIndex":0,"subject":"বাংলা","explanation":"মধ্যযুগের বাংলা সাহিত্যের আদি ও শ্রেষ্ঠ নিদর্শন 'শ্রীকৃষ্ণকীর্তন', যা সম্পূর্ণ বাংলা ভাষায় রচিত প্রথম গ্রন্থ; এর রচয়িতা মধ্যযুগের আদি কবি বড়ু চণ্ডীদাস। এ কাব্যে মোট ১৩টি খণ্ড রয়েছে, যার প্রথমটি জন্মখণ্ড (এরপর যথাক্রমে তাম্বুলখণ্ড, দানখণ্ড, নৌকাখণ্ড, ভারখণ্ড, ছত্রখণ্ড, বৃন্দাবনখণ্ড, কালিয়দমনখণ্ড, যমুনাখণ্ড, হারখণ্ড, বাণখণ্ড, বংশীখণ্ড ও বিরহখণ্ড)। ১৯০৯ সালে বসন্তরঞ্জন রায় বিদ্বদ্বল্লভ পশ্চিমবঙ্গের বাঁকুড়া জেলার কাঁকিল্যা গ্রামের একটি গোয়ালঘর থেকে কাব্যটি আবিষ্কার করেন, এবং ১৯১৬ সালে 'বঙ্গীয় সাহিত্য পরিষদ' থেকে এটি প্রকাশিত হয়।"},{"id":"bangla-40","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'লুই ভণই গুরু পুছিঅ জাণ।'-এখানে 'ভণই' শব্দের অর্থ কী?","options":["বলে","ভাবে","চায়","দেখে"],"correctIndex":0,"subject":"বাংলা","explanation":"লুই হলেন চর্যাপদের কবি লুইপা; 'ভণই' অর্থ বলে, 'গুরু' অর্থ শিক্ষক, 'পুছিঅ' অর্থ জিজ্ঞাসা করো, 'জাণ' অর্থ জ্ঞান। আধুনিক বাংলায় ছত্রটির অর্থ- কবি লুইপা বলেন, জ্ঞান লাভের জন্য গুরুকে জিজ্ঞাসা করো। এই পঙ্‌ক্তিটি চর্যাপদের ১নং পদের চরণ, যার রচয়িতা বাংলা সাহিত্যের আদি কবি লুইপা (চর্যার ১ ও ২৯ নং পদের রচয়িতা); তিনি সংস্কৃতে 'অভিসময় বিভঙ্গ' নামে একটি গ্রন্থ রচনা করেন।"},{"id":"bangla-41","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'শ্রীকৃষ্ণকীর্তন' কাব্যের অংশ নয় কোনটি?","options":["নৌকা খণ্ড","হার খণ্ড","রাধা বিরহ","প্রণয় খণ্ড"],"correctIndex":3,"subject":"বাংলা","explanation":"মধ্যযুগের বাংলা সাহিত্যের আদি ও শ্রেষ্ঠ নিদর্শন, বড়ু চণ্ডীদাস রচিত 'শ্রীকৃষ্ণকীর্তন' কাব্যে মোট ১৩টি খণ্ড রয়েছে- জন্মখণ্ড, তাম্বুলখণ্ড, দানখণ্ড, নৌকাখণ্ড, ভারখণ্ড, ছত্রখণ্ড, বৃন্দাবনখণ্ড, কালিয়দমনখণ্ড, যমুনাখণ্ড, হারখণ্ড, বাণখণ্ড, বংশীখণ্ড ও বিরহখণ্ড (বিরহখণ্ডকেই রাধাবিরহ বলা হয়)। এই তালিকায় 'প্রণয় খণ্ড' নামে কোনো খণ্ড নেই।"},{"id":"bangla-42","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"বিবৃত স্বরধ্বনি বলতে বোঝায়-","options":["যে স্বরধ্বনি উচ্চারণে ঠোঁট বেশি খোলে","যে স্বরধ্বনি উচ্চারণে জিভ উঁচু হয়","যে স্বরধ্বনি অবিকৃতভাবে উচ্চারিত হয়","যে স্বরধ্বনি উচ্চারণে বিকৃতি ঘটে"],"correctIndex":0,"subject":"বাংলা","explanation":"জিভের উচ্চতা ও ঠোঁটের উন্মুক্তি অনুযায়ী স্বরধ্বনির শ্রেণিবিভাগ করা হয়। বিবৃত স্বরধ্বনি উচ্চারণে ঠোঁট সবচেয়ে বেশি খোলে; বিবৃত স্বরধ্বনি একটি- 'আ', যা জিভের উচ্চতা অনুযায়ী নিম্ন স্বরধ্বনি। বিপরীতে, সংবৃত স্বরধ্বনি উচ্চারণের সময় ঠোঁট সবচেয়ে কম খোলে; সংবৃত স্বরধ্বনি দুটি- 'ই' ও 'উ', যা জিভের উচ্চতা অনুযায়ী উচ্চ স্বরধ্বনি। এই মাঝামাঝি ধাপে আছে অর্ধ-সংবৃত (এ, ও) ও অর্ধ-বিবৃত (অ্যা, অ) স্বরধ্বনি।"},{"id":"bangla-43","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"মনোয়েল দ্যা আসসুম্পসাঁও অভিধান প্রকাশের আগে কত বছর ধরে শব্দ সংগ্রহ করেন?","options":["২-৩ বছর","৫-৭ বছর","৯-১০ বছর","১৪-১৫ বছর"],"correctIndex":2,"subject":"বাংলা","explanation":"বাংলা অভিধানের সূচনা আঠারো শতকে, প্রথম দিকে যা ছিল প্রধানত দ্বিভাষিক। এ শ্রেণির প্রথম অভিধান 'Vocabulario em Idioma Bengalla e Portuguez' (সংক্ষেপে Vocabulario), যা পর্তুগিজ পাদ্রি মনোএল দা আসসুম্পসাঁউ ভাওয়ালের একটি গির্জায় ধর্মযাজকের দায়িত্ব পালনকালে খ্রিষ্টধর্ম প্রচারের সুবিধার্থে ১৭৩৪-৪২ খ্রিস্টাব্দের মধ্যে রচনা করেন এবং ১৭৪৩ সালে লিসবন থেকে রোমান হরফে মুদ্রিত হয়। এই অভিধান প্রকাশের আগে তিনি ৯-১০ বছর ধরে শব্দ সংগ্রহ করেন, মূলত পূর্ববঙ্গের ফরিদপুর জেলার লোকদের কথোপকথনের ভিত্তিতে। এটিই বাংলা ভাষার প্রথম ব্যাকরণ গ্রন্থও বটে, যার প্রথম অংশে বাংলা ব্যাকরণের সংক্ষিপ্তসার ও দ্বিতীয় অংশে বাংলা-পর্তুগিজ/পর্তুগিজ-বাংলা শব্দাভিধান রয়েছে; এতে রূপতত্ত্ব ও বাক্যতত্ত্ব আলোচিত হলেও ধ্বনিতত্ত্বের কোনো আলোচনা নেই।"},{"id":"bangla-44","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"গৌড়ী প্রাকৃত বলতে বোঝায়-","options":["গৌড় অঞ্চলের মুখের ভাষা","গৌড় সাহিত্যের স্বাভাবিক রীতি","গৌড় ভাষার লিখিত নমুনা","গৌড় ভাষার বিকৃত উচ্চারণ"],"correctIndex":0,"subject":"বাংলা","explanation":"গৌড়ী প্রাকৃত বলতে প্রাচীন ভারতের গৌড় অঞ্চলের মানুষের মুখের ভাষাকে বোঝায়। ড. মুহম্মদ শহীদুল্লাহর মতে খ্রিষ্টীয় সপ্তম শতকে গৌড়ীয় প্রাকৃত থেকে বাংলা ভাষার উদ্ভব হয়; তাঁর মতবাদ অনুযায়ী বাংলা ভাষার উৎপত্তির ধারা- প্রাকৃত > গৌড়ীয় প্রাকৃত > গৌড়ীয় অপভ্রংশ > বঙ্গকামরূপী > বাংলা। তুলনায়, মাগধী প্রাকৃত বলতে মগধ অঞ্চলের মুখের ভাষা বোঝায়; ড. সুনীতিকুমার চট্টোপাধ্যায়ের মতে খ্রিষ্টীয় দশম শতকে মাগধী প্রাকৃত থেকে বাংলা ভাষার উদ্ভব হয়।"},{"id":"bangla-45","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'Glossary' শব্দের বাংলা পরিভাষা-","options":["জ্ঞাপনপত্র","সর্বসাকল্যে","শব্দার্থপঞ্জি","গুদামজাত"],"correctIndex":2,"subject":"বাংলা","explanation":"'Glossary' শব্দের বাংলা পরিভাষা- শব্দপঞ্জি, শব্দার্থপঞ্জি, টীকাপুঞ্জ, টীকাগ্রন্থ বা শব্দকোষ। অপশন বিশ্লেষণ: Hand out-এর পরিভাষা জ্ঞাপনপত্র, In total-এর পরিভাষা সর্বসাকল্যে, আর Warehoused-এর পরিভাষা গুদামজাত।"},{"id":"bangla-46","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'ঐক্যমত' শব্দটি কোন বিবেচনায় অশুদ্ধ নয়?","options":["মতের ঐক্য - এভাবে সমাসসাধিত ধরলে","একমত + য - এভাবে প্রত্যয়সাধিত ধরলে","ঐক্য + মত - এভাবে উপসর্গসাধিত ধরলে","ঐক্যমত শব্দটিকে পারিভাষিক শব্দ ধরলে"],"correctIndex":0,"subject":"বাংলা","explanation":"'ঐক্যমত' শব্দটিকে 'মতের ঐক্য' অর্থে ৬ষ্ঠী তৎপুরুষ সমাসসাধিত ধরলে এটি অশুদ্ধ নয়। তবে প্রত্যয় দ্বারা গঠিত 'একমত+য' = 'ঐকমত্য' (অর্থ- একমত, মতের মিল) শব্দটিই বহুল প্রচলিত এবং প্রমিত/শুদ্ধ বানান হিসেবে স্বীকৃত।"},{"id":"bangla-47","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"১৯৩৬ সালে কলিকাতা বিশ্ববিদ্যালয়ের বানান সংস্কারের মূল উদ্দেশ্য ছিল-","options":["বানানকে উচ্চারণের কাছাকাছি নেওয়া","বানানের ঐতিহ্যকে বজায় রাখা","বানানের নিয়ম প্রণয়ন করা","বানানে বিকল্প বর্জন করা"],"correctIndex":2,"subject":"বাংলা","explanation":"বাংলা বানান প্রমিতকরণের প্রয়াস শুরু হয় উনিশ শতক থেকে। রবীন্দ্রনাথ ঠাকুরের উদ্যোগে ১৯৩৬ সালে কলকাতা বিশ্ববিদ্যালয় বানানের নিয়ম প্রণয়ন করলে বানানে অনেকটা শৃঙ্খলা ফিরে আসে। অর্থাৎ এই সংস্কারের মূল উদ্দেশ্য ছিল বানানের নিয়ম প্রণয়ন করা, যার একটি অংশ ছিল বানানে বিকল্প বর্জন করা।"},{"id":"bangla-48","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"অভিধানে ৎ, ঃ, ঁ, ং - এই বর্ণগুলোর অবস্থান কোথায়?","options":["স্বরবর্ণের আগে","স্বরবর্ণের শেষে","ব্যঞ্জনবর্ণের শেষে","এদের নির্দিষ্ট অবস্থান নেই"],"correctIndex":1,"subject":"বাংলা","explanation":"অভিধানে ব্যবহৃত বর্ণানুক্রম- অ আ ই ঈ উ ঊ ঋ এ ঐ ও ঔ, তারপর ং ঃ ঁ, তারপর ব্যঞ্জনবর্ণ (ক খ গ ঘ ঙ...ত(ৎ) থ দ ধ ন...ম য য় র ল শ ষ স হ)। অর্থাৎ ং, ঃ, ঁ- এই বর্ণগুলো স্বরবর্ণের শেষে (স্বরবর্ণের পরে ও ব্যঞ্জনবর্ণের আগে) বসে; আর 'ৎ' ব্যঞ্জনবর্ণের ক্রমে 'ত'-এর পরে নিজস্ব স্থানে বসে।"},{"id":"bangla-49","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"পূর্ববঙ্গীয় উচ্চারণে 'স্মরণ' শব্দের ক্ষেত্রে কোনটি ঘটে?","options":["স-এর উচ্চারণ শ হয়ে যায়","ণ-এর উচ্চারণ ন হয়ে যায়","ম-ফলার উচ্চারণ ম হয়ে যায়","শুরুতে নাসিক্য উচ্চারণ হয় না"],"correctIndex":0,"subject":"বাংলা","explanation":"পূর্ববঙ্গীয় (বাংলাদেশের) উচ্চারণরীতিতে প্রায়ই 'স'-এর উচ্চারণ 'শ' হয়ে যায়; যেমন- সাপ [শাপ্], স্মরণ [শঁরোন্], সাথী [শাথি]। অপশন বিশ্লেষণ: ন ও ণ ভিন্ন দুটি বর্ণ হলেও উচ্চারণ অভিন্ন, তাই 'স্মরণ' শব্দে ণ-এর উচ্চারণে বাড়তি কোনো পরিবর্তন ঘটে না (অপশন খ ভুল); ম-ফলা শব্দের শুরুতে উচ্চারিত হয় না বলে 'স্মরণ' শব্দে ম-ফলার উচ্চারণ 'ম' হয় না (অপশন গ ভুল); বরং শুরুতে ম উচ্চারিত না হয়ে নাসিক্য (ঁ) উচ্চারণ ঘটে (অপশন ঘ-ও ভুল)।"},{"id":"bangla-50","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'গড্ডালিকা প্রবাহ' বাগ্‌ধারার 'গড্ডল' শব্দের অর্থ কী?","options":["নদী","স্রোত","ভেড়া","মশা"],"correctIndex":2,"subject":"বাংলা","explanation":"গড্ডল/গড্ডর শব্দের অর্থ ভেড়া, মেষ, গাড়ল। গড্ডালিকা শব্দের অর্থ- অগ্রবর্তী ভেড়াকে অনুসরণকারী ভেড়ার পাল। 'গড্ডালিকা প্রবাহ' বাগ্‌ধারাটির অর্থ- বিচার-বিবেচনা না করে অন্যের অন্ধ অনুকরণ বা প্রচলিত ধারার অনুগামিতা।"},{"id":"bangla-51","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'বিরাট গরু-ছাগলের হাট'-ব্যানারে লেখা এই শিরোনামকে অপপ্রয়োগ বলা যায় না কেন?","options":["বিরাট শব্দটি হাটকে বিশেষিত করেছে","বিরাট শব্দটি গরু-ছাগলকে বিশেষিত করেছে","বিশেষণের অবস্থান যে-কোনো জায়গায় হতে পারে","বহুল ব্যবহারে প্রয়োগ-অশুদ্ধতা হারিয়েছে"],"correctIndex":0,"subject":"বাংলা","explanation":"'বিরাট' শব্দটি এখানে গরু-ছাগল সম্পর্কে নয়, বরং হাট সম্পর্কে তথ্য দিচ্ছে (প্রশ্ন: কেমন হাট? উত্তর: বিরাট হাট), তাই এটি অপপ্রয়োগ নয়। অনুরূপ উদাহরণ- 'খাঁটি সরিষার তেল' বাক্যাংশে 'খাঁটি' বিশেষণটি তেল সম্পর্কে তথ্য দেয় বলে এটিও সঠিক প্রয়োগ। অপশন বিশ্লেষণ: বিরাট শব্দটি গরু-ছাগলকে বিশেষিত করছে না, তাই অপশন (খ) ভুল; সাধারণত বিশেষণ বিশেষ্য/সর্বনামের পূর্বে বসলেও কখনো কখনো বাক্যের শুরুতে/মাঝে/শেষেও বসতে পারে, তবে অপশন (গ)-এ 'বিরাট' শব্দের উল্লেখই নেই বলে এটি সঠিক নয়; বহুল ব্যবহারে প্রয়োগ-অশুদ্ধতা হারানোর ধারণাটিও ভুল, কারণ বহুল ব্যবহৃত অশুদ্ধ শব্দ সাধারণত আধুনিক ব্যাকরণে ধীরে ধীরে শুদ্ধ করা হয়, এমনিতেই অশুদ্ধতা ঘুচে যায় না।"},{"id":"bangla-52","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'অজর' শব্দের বিপরীত কোনটি?","options":["অমলিন","বার্ধক্য","অমর","ব্যাধিগ্রস্ত"],"correctIndex":1,"subject":"বাংলা","explanation":"বাংলা একাডেমি আধুনিক বাংলা অভিধান অনুযায়ী 'অজর' শব্দের অর্থ জরারহিত/বার্ধক্যরহিত; এর বিপরীত শব্দ 'বার্ধক্য' (অর্থ- বৃদ্ধাবস্থা, বৃদ্ধ বয়স, জরা)। অপশন বিশ্লেষণ: অমলিন-এর বিপরীত মলিন; অমর-এর বিপরীত মরণশীল; ব্যাধিগ্রস্ত-এর বিপরীত নীরোগ/রোগমুক্ত।"},{"id":"bangla-53","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'ব্যাং' শব্দটি ং দিয়ে লিখতে হবে, কারণ-","options":["ঙ-এর হসন্ত উচ্চারণ ং হয়","য্‌ফলার পর ং হয়","ং বাংলা ভাষার নিজস্ব বর্ণ","ব্যাং একটি একাক্ষর শব্দ"],"correctIndex":0,"subject":"বাংলা","explanation":"ঙ-এর হসন্ত উচ্চারণ ং হয়, তাই 'ব্যাং' শব্দটি ং দিয়ে লিখতে হয়; 'ব্যাঙ্' এভাবে লেখা ভুল। অনুরূপভাবে 'রঙ্', 'ঢঙ্' লেখা ভুল, সঠিক হবে 'রং', 'ঢং'। তবে ং-এর পর স্বরচিহ্ন/কারচিহ্ন যুক্ত হলে সেখানে 'ঙ' বসে, যেমন- ব্যাঙাচি, রঙিন, ঢঙি।"},{"id":"bangla-54","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'সে কৌতুক করার কৌতূহল সংবরণ করতে পারল না।'-এই বাক্য কী কারণে ত্রুটিপূর্ণ?","options":["বানান ভুল আছে","বাক্যের পদবিন্যাস যথাযথ নয়","অর্থ অনুযায়ী শব্দের প্রয়োগ হয়নি","বিশেষ্য-বিশেষণের অপপ্রয়োগ ঘটেছে"],"correctIndex":2,"subject":"বাংলা","explanation":"কৌতুক শব্দের অর্থ আমোদ/মজা/পরিহাস, কৌতূহল শব্দের অর্থ অজ্ঞাত বিষয় জানার আগ্রহ (ঔৎসুক্য), আর সংবরণ শব্দের অর্থ নিবারণ/দমন। ফলে 'সে কৌতুক করার কৌতূহল সংবরণ করতে পারল না।' বাক্যটির অর্থ দাঁড়ায়- সে মজা করার অজ্ঞাত বিষয় জানার আগ্রহ দমন করতে পারল না, যা অর্থহীন শোনায়- কারণ এখানে অর্থ অনুযায়ী শব্দের যথাযথ প্রয়োগ হয়নি। সঠিক রূপ হবে- 'সে কৌতুক করার আগ্রহ/ইচ্ছা সংবরণ করতে পারল না।' অপশন বিশ্লেষণ: বাক্যটির সব বানান সঠিক (তাই ক ভুল); পদবিন্যাসও যথাযথ- কর্তা (সে), কর্ম (কৌতূহল), ক্রিয়া (পারল না) যথাক্রমে বসেছে (তাই খ ভুল); বিশেষ্য-বিশেষণের কোনো অপপ্রয়োগও ঘটেনি (তাই ঘ ভুল)।"},{"id":"bangla-55","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'নিত্য তোমার যে ফুল ফোটে ফুলবনে'-এখানে 'নিত্য' শব্দের প্রতিশব্দ কোনটি?","options":["অতিশয়","চিরন্তন","প্রকৃতি","অহরহ"],"correctIndex":3,"subject":"বাংলা","explanation":"বাংলা একাডেমি আধুনিক বাংলা অভিধান অনুযায়ী 'নিত্য' শব্দের প্রতিশব্দ- প্রত্যহ, অহরহ। উল্লেখ্য, 'নিত্য তোমার যে ফুল ফোটে ফুলবনে, তারি মধু কেন মনমধুপে খাওয়াও না?' পঙ্‌ক্তিটি রবীন্দ্রনাথ ঠাকুরের একটি গানের লাইন।"},{"id":"bangla-56","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"বাক্যের মধ্যে শব্দ অবস্থান করে কীভাবে?","options":["কর্তা ও ক্রিয়ার পদবিন্যাস অনুযায়ী","অর্থ ও ভাব অনুযায়ী","বর্গ বা গুচ্ছ আকারে","স্বাধীন পদের পরিচয় নিয়ে"],"correctIndex":1,"subject":"বাংলা","explanation":"একাধিক অর্থবোধক শব্দ পাশাপাশি বসে মনের ভাব প্রকাশ করলে তাকে বাক্য বলে; বাক্যের মধ্যে শব্দ মূলত অর্থ ও ভাব অনুযায়ী অবস্থান করে। যেমন 'পাখি আকাশে ওড়ে' সঠিক বাক্য, কারণ 'ওড়ে' ক্রিয়ার সাথে 'পাখি' শব্দের অর্থগত ও ভাবগত মিলবন্ধন আছে। অপশন বিশ্লেষণ: কর্তা-ক্রিয়ার পদবিন্যাস ঠিক থাকলেও অর্থ-ভাবের মিল না থাকলে বাক্য ভুল হতে পারে (যেমন- 'হাতি আকাশে ওড়ে'), তাই কেবল পদবিন্যাস নির্ধারক নয়; বাক্যে শব্দ সবসময় বর্গ/শব্দগুচ্ছ আকারে অবস্থান করে না (যেমন- 'বাবা বাড়ি আছে'-তে কোনো বর্গ নেই); আর প্রতিটি পদ স্বাধীন পদের পরিচয় নিয়ে বসলেও অর্থ-ভাবের সংগতি না থাকলে তা বাক্য গঠন করতে পারে না।"},{"id":"bangla-57","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"বাংলা একাডেমির 'আধুনিক বাংলা অভিধান'-এর সম্পাদক কে?","options":["আনিসুজ্জামান","আবু ইসহাক","মনসুর মুসা","জামিল চৌধুরি"],"correctIndex":3,"subject":"বাংলা","explanation":"'বাংলা একাডেমি আধুনিক বাংলা অভিধান'-এর সম্পাদক জামিল চৌধুরি। তুলনায়- 'আমার অভিধান'-এর সম্পাদক আনিসুজ্জামান; 'বাংলা একাডেমী সমকালীন বাংলা ভাষার অভিধান'-এর সম্পাদক আবু ইসহাক; 'বাংলায় প্রচলিত ইংরেজি শব্দের অভিধান'-এর সম্পাদক মনসুর মুসা ও মনোয়ার ইলিয়াস।"},{"id":"bangla-58","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'আলালের ঘরে দুলাল' প্রথমে কোন পত্রিকায় ধারাবাহিকভাবে প্রকাশিত হয়?","options":["বিবিধার্থ সংগ্রহ","সংবাদ প্রভাকর","মাসিক পত্রিকা","বঙ্গদর্শন"],"correctIndex":2,"subject":"বাংলা","explanation":"প্যারীচাঁদ মিত্র রচিত 'আলালের ঘরের দুলাল' (প্রকাশ ১৮৫৭, মতান্তরে ১৮৫৮) বাংলা সাহিত্যের প্রথম উপন্যাস; এটি প্রথমে 'মাসিক পত্রিকা'-য় ধারাবাহিকভাবে প্রকাশিত হয় (এই পত্রিকা ১৮৫৪ সালে প্যারীচাঁদ মিত্র ও রাধানাথ শিকদার যৌথভাবে প্রতিষ্ঠা ও সম্পাদনা করেন)। পরবর্তীতে হীরালাল মিত্র কর্তৃক এর নাট্যরূপ বেঙ্গল থিয়েটারে মঞ্চস্থ হয় (জানুয়ারি ১৮৭৫)। উপন্যাসটির মূল বিষয়বস্তু কলকাতার সমকালীন সমাজ ও উচ্চবিত্ত ঘরের আদুরে সন্তান মতিলালের উচ্ছৃঙ্খল জীবনাচার; চরিত্র- ঠকচাচা, মতিলাল, রামলাল, বাবুরাম, বাঞ্ছারাম। এই উপন্যাসে প্যারীচাঁদ মিত্র প্রথমবারের মতো যে কথ্য চলিত ভাষা ব্যবহার করেন, তা 'আলালী ভাষা' নামে পরিচিত।"},{"id":"bangla-59","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"কাজী নজরুল ইসলামের কোন গ্রন্থটি বাজেয়াপ্ত হয়নি?","options":["অগ্নিবীণা","বিষের বাঁশি","ভাঙার গান","চন্দ্রবিন্দু"],"correctIndex":0,"subject":"বাংলা","explanation":"কাজী নজরুল ইসলামের মোট ৫টি গ্রন্থ নিষিদ্ধ হয়- যুগবাণী (প্রথম নিষিদ্ধ গ্রন্থ/প্রবন্ধ সংকলন), বিষের বাঁশি (দ্বিতীয় নিষিদ্ধ গ্রন্থ/প্রথম নিষিদ্ধ কাব্যগ্রন্থ), ভাঙার গান, প্রলয় শিখা ও চন্দ্রবিন্দু। গ্রন্থ হিসেবে 'অগ্নি-বীণা' কাব্য কখনোই নিষিদ্ধ হয়নি, তবে এর অন্তর্গত 'রক্তাম্বরধারিণী মা' কবিতাটি একক কবিতা হিসেবে বাজেয়াপ্ত হয়। 'অগ্নি-বীণা' (১৯২২) নজরুলের প্রথম কাব্যগ্রন্থ, যাতে মোট ১২টি হিন্দু-মুসলিম ঐতিহ্যভিত্তিক কবিতা আছে; প্রথম কবিতা 'প্রলয়োল্লাস' এবং শেষ কবিতা 'মোহররম'।"},{"id":"bangla-60","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"জসীম উদ্‌দীনের 'কবর' কবিতাটি কোন কাব্যের অন্তর্গত?","options":["বালুচর","রাখালী","ধানক্ষেত","মা যে জননী কান্দে"],"correctIndex":1,"subject":"বাংলা","explanation":"জসীম উদ্‌দীনের প্রথম প্রকাশিত কাব্যগ্রন্থ 'রাখালী' (১৯২৭); এর অন্তর্গত তাঁর বিখ্যাত কবিতা 'কবর', যা প্রথম প্রকাশিত হয় 'কল্লোল' পত্রিকায় ১৩৩২ বঙ্গাব্দের শ্রাবণ সংখ্যায়। কবি দশম শ্রেণির ছাত্র থাকাকালে মাত্রাবৃত্ত ছন্দে এটি রচনা করেন; কবিতাটিতে ১১৮টি পঙ্‌ক্তি আছে এবং Dramatic Monologue রীতিতে একজন গ্রামীণ বৃদ্ধের একে একে প্রিয়জন হারানোর বেদনা ফুটে উঠেছে। রাখালী কাব্যের অন্যান্য কবিতা- পল্লীজননী, রাখাল ছেলে, বৈদেশী বন্ধু, তরুণ কিশোর, পাহাড়িয়া, কৃষাণ দুলালী।"},{"id":"bangla-61","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'সকলের তরে সকলে আমরা/ প্রত্যেকে আমরা পরের তরে।'- কোন কবিতার অংশ?","options":["পরার্থে","পাছে লোকে কিছু বলে","বড় কে","সুখ"],"correctIndex":3,"subject":"বাংলা","explanation":"প্রশ্নোক্ত চরণ দুটি কামিনী রায়ের 'সুখ' কবিতার অংশবিশেষ, যা তাঁর প্রথম কাব্যগ্রন্থ 'আলো ও ছায়া'-র অন্তর্গত (মাত্র ১৫ বছর বয়সে রচিত)। পুরাতন বোর্ড বইতে ভুলবশত এই চরণগুলো নিয়ে 'পরার্থে' নামে একটি পৃথক কবিতা সংযোজিত হয়েছিল, কিন্তু প্রকৃতপক্ষে কামিনী রায়ের 'পরার্থে' নামে কোনো কবিতা নেই; বর্তমান বোর্ড বইতে মূল কবিতার নাম অনুসারে 'সুখ' কবিতাই অন্তর্ভুক্ত রয়েছে। তাই অপশনে 'সুখ' ও 'পরার্থে' উভয়ই থাকলে সঠিক উত্তর হিসেবে 'সুখ' বেছে নিতে হয়।"},{"id":"bangla-62","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'এমন পিরিতি কভু নাহি দেখি শুনি।/ পরানে পরান বান্ধা আপনা আপনি॥'-কার লেখা?","options":["বিদ্যাপতি","চণ্ডীদাস","জ্ঞানদাস","গোবিন্দদাস"],"correctIndex":1,"subject":"বাংলা","explanation":"বৈষ্ণব কবি চণ্ডীদাসকে বাংলা সাহিত্যের প্রথম মানবতাবাদী কবি বলা হয়; উদ্ধৃত পঙ্‌ক্তিদ্বয় তাঁরই বিখ্যাত রচনা। তাঁর আরেকটি বিখ্যাত পঙ্‌ক্তি- 'সবার উপরে মানুষ সত্য তাহার উপরে নাই।' চণ্ডীদাসের জন্ম পশ্চিমবঙ্গের বীরভূম জেলার নান্নুর গ্রামে (মতান্তরে বাঁকুড়ার ছাতনায়); তিনি বৈষ্ণব পদাবলির বাংলা ভাষার আদি কবি/প্রথম বাঙালি কবি। রবীন্দ্রনাথ ঠাকুর তাঁকে 'দুঃখের কবি' এবং 'সহজ ভাষায় সহজ ভাবের কবি' বলে অভিহিত করেছেন। অপশন বিশ্লেষণ: বিদ্যাপতির বিখ্যাত পঙ্‌ক্তি 'এ সখি হামারি দুখের নাহি ওর'; জ্ঞানদাসের 'সুখের লাগিয়া এ ঘর বাঁধিনু অনলে পুড়িয়া গেল'; গোবিন্দদাসের 'নন্দ নন্দন চন্দ চন্দন গন্ধ নিন্দিত অঙ্গ'।"},{"id":"bangla-63","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"ফোর্ট উইলিয়াম কলেজ পর্বে রচিত বাংলা বইগুলো-","options":["সংস্কৃত বইয়ের অনুবাদ","ফরাসি বইয়ের অনুবাদ","ইংরেজি বইয়ের অনুবাদ","পণ্ডিতদের রচিত মৌলিক গ্রন্থ"],"correctIndex":0,"subject":"বাংলা","explanation":"ইস্ট ইন্ডিয়া কোম্পানির ব্রিটিশ কর্মকর্তাদের এদেশীয় ভাষা ও সংস্কৃতি শেখানোর উদ্দেশ্যে প্রতিষ্ঠিত ফোর্ট উইলিয়াম কলেজের অবদান বাংলা গদ্য সাহিত্য বিকাশে সবচেয়ে বেশি। এই পর্বে অল্প কিছু মৌলিক গ্রন্থ (যেমন উইলিয়াম কেরির 'কথোপকথন', রামরাম বসুর 'রাজা প্রতাপাদিত্য চরিত্র') রচিত হলেও অধিকাংশ বই ছিল সংস্কৃত গ্রন্থের অনুবাদ; যেমন মৃত্যুঞ্জয় বিদ্যালঙ্কারের বত্রিশ সিংহাসন (সংস্কৃত কথাসাহিত্যের অনুবাদ), রাজাবলি (সংস্কৃত ইতিহাসের অনুবাদ), হিতোপদেশ ও প্রবোধ চন্দ্রিকা (উভয়ই সংস্কৃত গ্রন্থের অনুবাদ); এছাড়া গোলকনাথ শর্মার হিতোপদেশ এবং হরপ্রসাদ রায়ের পুরুষপরীক্ষাও সংস্কৃত অনুবাদ।"},{"id":"bangla-64","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"সাহিত্যের রূপ ও রীতির বিচারে কোন গ্রন্থটি ব্যতিক্রম?","options":["বাংলা কাব্য","দিবারাত্রির কাব্য","শেষের কবিতা","নদী ও নারী"],"correctIndex":0,"subject":"বাংলা","explanation":"দিবারাত্রির কাব্য (মানিক বন্দ্যোপাধ্যায়), শেষের কবিতা (রবীন্দ্রনাথ ঠাকুর) ও নদী ও নারী (হুমায়ুন কবির)- এই তিনটিই মূলত উপন্যাস, যদিও নামে 'কাব্য'/কাব্যধর্মী শব্দ যুক্ত আছে। অন্যদিকে 'বাংলা কাব্য' নামে কোনো নির্দিষ্ট গ্রন্থ নেই- এটি বাংলা সাহিত্যের কবিতার সামগ্রিক রূপ/ধারাকে নির্দেশ করে, নির্দিষ্ট কোনো রচনার শিরোনাম নয়। সাহিত্যের রূপ ও রীতির বিচারে তাই 'বাংলা কাব্য' এই চারটির মধ্যে ব্যতিক্রম হিসেবে বিবেচিত হয়।"},{"id":"bangla-65","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"কোন্ মঙ্গলকাব্যে ঐতিহাসিক চরিত্র আছে?","options":["মনসামঙ্গল","চণ্ডীমঙ্গল","অন্নদামঙ্গল","ধর্মমঙ্গল"],"correctIndex":2,"subject":"বাংলা","explanation":"মঙ্গলকাব্য ধারার সর্বশেষ ও অষ্টাদশ শতাব্দীর শ্রেষ্ঠ কাব্য 'অন্নদামঙ্গল', রচয়িতা ভারতচন্দ্র রায় গুণাকর। কাব্যটি ৩ খণ্ডে বিভক্ত ও তিনটি স্বতন্ত্র কাহিনিতে পূর্ণ- প্রথম খণ্ডে শিবায়ন-অন্নদামঙ্গল (পৌরাণিক), দ্বিতীয় খণ্ডে বিদ্যাসুন্দর-কালিকামঙ্গল, তৃতীয় খণ্ডে মানসিংহ-ভবানন্দের কাহিনি, যা মূলত ঐতিহাসিক। মুঘল সম্রাট আকবরের সেনাপতি মানসিংহ কর্তৃক রাজা প্রতাপাদিত্যকে পরাজয় ও বন্দিকরণ এবং সম্রাট জাহাঙ্গীরের নিকট থেকে ভবানন্দের 'রাজা-ই-ফরমান' লাভের মতো ঐতিহাসিক ঘটনা এই তৃতীয় অংশে বর্ণিত হয়েছে, ফলে অন্নদামঙ্গল কাব্যে ঐতিহাসিক চরিত্র রয়েছে।"},{"id":"bangla-66","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"কোন্ কাব্যে আলাওল ব্যক্তিগত জীবনের কথা লিখেছেন?","options":["পদ্মাবতী","হপ্তপয়কর","সিকান্দরনামা","তোহফা"],"correctIndex":0,"subject":"বাংলা","explanation":"আরাকান রাজসভার শ্রেষ্ঠ কবি ও সপ্তদশ শতকের শ্রেষ্ঠ মুসলিম কবি আলাওল ১৬০৭ সালে ফতেহাবাদ পরগনা, ফরিদপুরে (মতান্তরে চট্টগ্রামের হাটহাজারীর জোবরা গ্রামে) জন্মগ্রহণ করেন। তাঁর মোট সাতটি কাব্যের মধ্যে প্রথম ও শ্রেষ্ঠ কাব্য 'পদ্মাবতী', যেখানে তিনি নিজের ব্যক্তিগত জীবনের কথা বিশেষভাবে তুলে ধরেছেন এবং পদ্মাবতীর রূপ বর্ণনায় কৃতিত্ব দেখিয়েছেন (নায়ক রত্নসেন, নায়িকা পদ্মাবতী, শুক পাখি হিরামন)। এছাড়া হপ্তপয়কর (ফারসি থেকে অনূদিত সাতটি গল্পের সংকলন, বাংলা নাম সপ্তপয়কর) ও সিকান্দরনামা (আলেকজান্ডারের দিগ্বিজয়ের কাহিনি) নিয়ামী গঞ্জাবীর কাব্যের অনুবাদ, আর তোহফা মূলত ধর্মীয় তত্ত্বোপদেশমূলক নীতিকাব্য।"},{"id":"bangla-67","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'তুরস্ক-ভ্রমণ' কার লেখা?","options":["ইসমাইল হোসেন সিরাজী","সৈয়দ মুজতবা আলী","আবু জাফর শামসুদ্দীন","শামসুদ্দীন আবুল কালাম"],"correctIndex":0,"subject":"বাংলা","explanation":"সৈয়দ ইসমাইল হোসেন সিরাজী রচিত ভ্রমণকাহিনি 'তুরস্ক-ভ্রমণ'-এর পটভূমি বলকান যুদ্ধ (১৯১২-১৯১৩); এই যুদ্ধকালে তিনি 'অল ইন্ডিয়া মেডিকেল মিশন'-এর বঙ্গীয় প্রতিনিধি হিসেবে তুরস্কে যান এবং তুর্কি স্বাস্থ্য অধিদপ্তরের ইন্সপেক্টরের দায়িত্ব পালন করেন; যুদ্ধ শেষে তুরস্ক সরকার তাঁকে 'গাজী এ বলকান' (১৯১৩) উপাধি দেয়। গ্রন্থে তিনি তৎকালীন তুরস্কের সমাজ-সংস্কৃতি ও ঐতিহাসিক প্রেক্ষাপট তুলে ধরেন। উপমহাদেশের প্রথম ব্রিটিশবিরোধী মুসলিম কবি হিসেবে পরিচিত সিরাজগঞ্জে জন্ম নেওয়া এই লেখক, বাগ্মী ও কৃষক নেতার জন্মস্থানের নামানুসারেই তাঁর নামের সাথে 'সিরাজী' উপাধি যুক্ত হয়।"},{"id":"bangla-68","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"সৈয়দ ওয়ালীউল্লাহর 'চাঁদের অমাবস্যা' উপন্যাসে কোন জীবনদর্শনের রূপায়ণ ঘটেছে?","options":["মার্কসবাদ","বাস্তববাদ","অস্তিত্ববাদ","পরাবাস্তববাদ"],"correctIndex":2,"subject":"বাংলা","explanation":"বাংলা ভাষায় মাত্র তিনটি উপন্যাস লিখে অসামান্য খ্যাতি অর্জনকারী সৈয়দ ওয়ালীউল্লাহর দ্বিতীয় উপন্যাস 'চাঁদের অমাবস্যা' (ষাটের দশকে ঢাকা থেকে প্রকাশিত) একটি মনস্তাত্ত্বিক উপন্যাস, যেখানে অস্তিত্ববাদের চিত্র দারুণভাবে উপস্থাপিত হয়েছে। উপন্যাসের কেন্দ্রীয় চরিত্র আরেফ আলী, একটি মাধ্যমিক স্কুলের শিক্ষক, যিনি প্রভাবশালী প্রতিষ্ঠাতা পরিবারের ছেলে কাদেরের ধর্ষণ ও হত্যাকাণ্ডের প্রত্যক্ষদর্শী হওয়ার পর মনস্তাত্ত্বিক দ্বন্দ্বে ভোগেন। সৈয়দ ওয়ালীউল্লাহর 'চাঁদের অমাবস্যা' ও 'কাঁদো নদী কাঁদো'- এই দুই ব্যতিক্রমধর্মী উপন্যাসে যথাক্রমে অস্তিত্ববাদ ও চেতনাপ্রবাহরীতির অসাধারণ রূপক প্রকাশ পেয়েছে।"},{"id":"bangla-69","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'প্রভাতফেরির মিছিল যাবে/ ছড়াও ফুলের বন্যা,/ বিষাদগীতি গাইছে পথে/ তিতুমীরের কন্যা।'-কার লেখা?","options":["শামসুর রাহমান","আল মাহমুদ","আহসান হাবীব","আবদুল গাফ্‌ফার চৌধুরী"],"correctIndex":1,"subject":"বাংলা","explanation":"প্রশ্নোল্লিখিত চরণগুলো কবি আল মাহমুদের 'একুশের কবিতা' থেকে উদ্ধৃত, যেখানে ভাষা আন্দোলনের শহিদদের প্রতি শ্রদ্ধা নিবেদন এবং তাঁদের আত্মত্যাগের মহিমা তুলে ধরা হয়েছে। কবিতায় ভাষাশহিদ বরকত ও ক্ষুদিরামের আত্মত্যাগের প্রসঙ্গও উঠে আসে।"},{"id":"bangla-70","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'হরফের ছড়া' কার লেখা বর্ণশিক্ষার বই?","options":["ঈশ্বরচন্দ্র বিদ্যাসাগর","রবীন্দ্রনাথ ঠাকুর","ফররুখ আহমদ","বন্দে আলী মিয়া"],"correctIndex":2,"subject":"বাংলা","explanation":"মুসলিম রেনেসাঁর কবি, ইসলামি স্বাতন্ত্র্যবাদী কবি ও মুসলিম পুনর্জাগরণের কবি নামে পরিচিত ফররুখ আহমদ রচিত বর্ণশিক্ষার বই 'হরফের ছড়া', যা শিশুদের ছড়ার মাধ্যমে বাংলা বর্ণমালা শেখানোর উদ্দেশ্যে লেখা। তাঁর অন্যান্য শিশুতোষ গ্রন্থ- পাখির বাসা (তাঁর প্রথম প্রকাশিত শিশুতোষ গ্রন্থ, যার জন্য ইউনেস্কো পুরস্কার লাভ করেন), নতুন লেখা, ছড়ার আসর, চাঁদের আসর, চিড়িয়াখানা, ফুলের জলসা। অপশন বিশ্লেষণ: ঈশ্বরচন্দ্র বিদ্যাসাগর রচিত শিশুদের বাংলা বর্ণমালার প্রথম সার্থক গ্রন্থ 'বর্ণপরিচয়'; রবীন্দ্রনাথ ঠাকুরের শিশুসাহিত্য 'সহজ পাঠ'; বন্দে আলী মিয়ার শিশুসাহিত্য- চোর জামাই, মেঘ কুমারী, সোনার হরিণ, শেয়াল পণ্ডিতের পাঠশালা প্রভৃতি।"},{"id":"bangla-71","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'রক্তকরবী' নাটকের অন্তর্গত বিষয় কী?","options":["নতুনের জয়গান গাওয়া","সামন্তবাদের বিলুপ্তি দেখানো","শ্রমিকদের অপ্রাপ্তি তুলে ধরা","পুঁজিবাদের নেতিবাচক প্রভাব দেখানো"],"correctIndex":3,"subject":"বাংলা","explanation":"রবীন্দ্রনাথ ঠাকুরের সাংকেতিক নাটক 'রক্তকরবী' ১৯২৩ সালে (বাংলা ১৩৩০ সন) শিলং-এর শৈলবাসে রচিত হয়, তখন এর নাম ছিল 'যক্ষপুরী'। ১৯২৪ সালে (১৩৩১ সনের আশ্বিন মাসে) 'প্রবাসী'-তে প্রকাশের সময় নাম হয় 'রক্তকরবী'। নাটকের মূল প্রতিপাদ্য পুঁজিবাদী শোষণের নেতিবাচক প্রভাব- কীভাবে আধুনিক যন্ত্রসভ্যতা মানুষকে কেবল উৎপাদনের হাতিয়ারে পরিণত করে এবং মানবিক সম্পর্ক ও আবেগ ধ্বংস করে দেয়, তা এতে দেখানো হয়েছে। উল্লেখযোগ্য চরিত্র- কিশোর, রঞ্জন, নন্দিনী।"},{"id":"bangla-72","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"মীর মশাররফ হোসেন সম্পর্কে কোন তথ্যটি যথার্থ নয়?","options":["তিন খণ্ডে 'বিষাদ-সিন্ধু' রচনা করেন","নিজের জীবনী রচনা করেন","জমিদারি দেখাশোনার কাজ করেছেন","বিবি কুলসুম তাঁর প্রথম স্ত্রী"],"correctIndex":3,"subject":"বাংলা","explanation":"মীর মশাররফ হোসেন আধুনিক বাংলা মুসলমান সাহিত্যিকদের পথিকৃৎ, প্রথম বাঙালি মুসলিম নাট্যকার ও প্রথম মুসলিম ঔপন্যাসিক। তিনি তিন খণ্ডে (মহরম পর্ব, উদ্ধার পর্ব, এজিদবধ পর্ব) 'বিষাদ-সিন্ধু' রচনা করেন, যা কারবালার বিষাদময় ঘটনা অবলম্বনে রচিত বাংলা সাহিত্যের একমাত্র গদ্য মহাকাব্য। তিনি নিজের জীবনীও রচনা করেন (উদাসীন পথিকের মনের কথা, গাজী মিয়াঁর বস্তানী) এবং কর্মজীবন শুরু করেন পিতার পদমদী এস্টেট (রাজবাড়ী) জমিদারি দেখাশোনার মাধ্যমে, পরে ফরিদপুর নবাব এস্টেটে এবং ১৮৮৫ সালে দেলদুয়ার এস্টেটের ম্যানেজার নিযুক্ত হন। তবে 'বিবি কুলসুম তাঁর প্রথম স্ত্রী' তথ্যটি যথার্থ নয়- তাঁর প্রথম স্ত্রীর নাম নওয়াবুন নেছা, দ্বিতীয় স্ত্রীর নাম বিবি কুলসুম; 'বিবি কুলসুম' তাঁর সর্বশেষ ও জীবনীমূলক রচনাগুলোর মধ্যে শ্রেষ্ঠত্বের দাবিদার গ্রন্থও বটে।"},{"id":"bangla-73","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"জীবনানন্দ দাশের মৃত্যুর পর কোন কাব্যগ্রন্থটি প্রকাশিত হয়?","options":["ঝরাপালক","রূপসী বাংলা","বনলতা সেন","সাতটি তারার তিমির"],"correctIndex":1,"subject":"বাংলা","explanation":"ত্রিশ দশকের কবি ও পঞ্চপাণ্ডবদের একজন জীবনানন্দ দাশ (১৮৯৯-১৯৫৪)-এর জীবিতাবস্থায় প্রকাশিত কাব্যগ্রন্থ যথাক্রমে- ঝরাপালক (১৯২৭, প্রথম), ধূসর পাণ্ডুলিপি (১৯৩৬), বনলতা সেন (১৯৪২), মহাপৃথিবী (১৯৪৪), এবং সাতটি তারার তিমির (১৯৪৮, জীবদ্দশায় প্রকাশিত সর্বশেষ কাব্য)। তাঁর মৃত্যুর পর প্রকাশিত কাব্যগ্রন্থ- রূপসী বাংলা (১৯৫৭) ও বেলা অবেলা কালবেলা (১৯৬১); তাঁর প্রথম প্রবন্ধগ্রন্থ 'কবিতার কথা'-ও মৃত্যুর পর ১৯৫৫ সালে প্রকাশিত হয়।"},{"id":"bangla-74","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'তুমি অধম তাই বলিয়া আমি উত্তম না হইব কেন?'- কোন উপন্যাসে আছে?","options":["বঙ্কিমচন্দ্রের 'কপালকুণ্ডলা'","রবীন্দ্রনাথের 'গোরা'","শরৎচন্দ্রের 'চরিত্রহীন'","বিভূতিভূষণের 'আরণ্যক'"],"correctIndex":0,"subject":"বাংলা","explanation":"বঙ্কিমচন্দ্র চট্টোপাধ্যায়ের 'কপালকুণ্ডলা' (১৮৬৬) বাংলা সাহিত্যের প্রথম রোমান্টিক উপন্যাস। এই উপন্যাসের বিখ্যাত উক্তিগুলোর একটি- 'তুমি অধম তাই বলিয়া আমি উত্তম না হইব কেন?' অন্য দুটি বিখ্যাত উক্তি- 'প্রদীপ নিবিয়া গেল' এবং 'পথিক তুমি পথ হারাইয়াছ?' (যা বাংলা সাহিত্যের প্রথম রোমান্টিক সংলাপ হিসেবে পরিচিত)। উপন্যাসের চরিত্রসমূহ- কপালকুণ্ডলা, নবকুমার, মতিবিবি (লুৎফুন্নিসা)।"}];
